css:
/*
 * Zerra — application styles
 * Dark-only, evidence-led call-to-action interface.
 *
 * Organization:
 *   1. Design tokens and global foundations
 *   2. Header/navigation and page layouts
 *   3. Home storytelling, evidence, video, objections, and actions
 *   4. Interior SPA views and resource directories
 *   5. Local-resource finder and production footer
 *   6. Responsive behavior
 *
 * Note: Some later rules intentionally refine earlier component rules.
 * They are retained to preserve the tested kodeWeave behavior.
 */

:root {
  --bg:#111512;
  --deep:#090c0a;
  --panel:#181e19;
  --panel2:#202821;
  --text:#f5f6f2;
  --muted:#aab4ac;
  --green:#9fe2aa;
  --lime:#d0ff9e;
  --line:#343d35
}

* {
  box-sizing:border-box
}

html {
  scroll-behavior:smooth
}

body {
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif
}

a {
  color:inherit
}

.site-header {
  position:sticky;
  top:0;
  z-index:40;
  height:68px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:0 max(20px,calc((100vw - 1180px)/2));
  background:rgba(17,21,18,.95);
  backdrop-filter:blur(15px);
  border-bottom:1px solid var(--line)
}

.brand {
  text-decoration:none
}

nav {
  display:flex;
  gap:20px
}

nav a {
  text-decoration:none;
  color:var(--muted);
  font-size:.82rem;
  font-weight:850
}

.menu-btn {
  display:none;
  width:44px;
  height:44px;
  background:none;
  border:1px solid var(--line);
  border-radius:8px;
  padding:10px
}

.menu-btn i {
  display:block;
  height:2px;
  background:white;
  margin:5px
}

.mobile-menu {
  position:absolute;
  top:68px;
  left:0;
  right:0;
  background:#0b0f0c;
  border-bottom:1px solid var(--line);
  padding:12px 20px
}

.mobile-menu a {
  display:block;
  padding:16px 4px;
  border-bottom:1px solid var(--line);
  text-decoration:none;
  font-weight:850
}

.hero,.mother,.evidence,.cinema,.excuses,.action,.final {
  max-width:1180px;
  margin:auto;
  padding:95px 20px
}

.hero {
  display:grid;
  grid-template-columns:1.05fr .95fr;
  gap:35px;
  align-items:center;
  min-height:calc(100vh - 68px)
}

.eyebrow,.heading>span,.mother>span,.final>span {
  color:var(--green);
  font-size:.7rem;
  letter-spacing:.17em;
  font-weight:950
}

.hero h1,.mother h2,.heading h2,.final h2 {
  font-size:clamp(3.3rem,8vw,7rem);
  line-height:.88;
  letter-spacing:-.065em;
  margin:18px 0 28px
}

.hero h1 em,.final h2 em {
  font-style:normal;
  color:var(--lime)
}

.hero-copy>p {
  font-size:1.2rem;
  color:var(--muted);
  line-height:1.7
}

.buttons {
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  margin-top:28px
}

.primary,.ghost {
  padding:14px 19px;
  border-radius:8px;
  border:1px solid var(--green);
  font-weight:900;
  text-decoration:none;
  cursor:pointer
}

.primary {
  background:var(--lime);
  color:#132015
}

.ghost {
  background:none;
  color:white
}

.hero-photo {
  margin:0;
  position:relative
}

.hero-photo img {
  width:100%;
  height:520px;
  object-fit:cover;
  filter:saturate(.75) contrast(1.08)
}

.hero-photo:after {
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(0deg,rgba(8,12,9,.65),transparent 55%);
  pointer-events:none
}

.hero-photo figcaption {
  position:absolute;
  z-index:2;
  bottom:15px;
  left:18px;
  right:18px;
  font-size:.72rem;
  color:#d5ddd6
}

.hero-photo figcaption a {
  color:var(--lime)
}

.live {
  grid-column:1/-1;
  border-top:1px solid var(--line);
  padding-top:25px
}

.live>span {
  font-size:.67rem;
  color:var(--green);
  letter-spacing:.1em;
  font-weight:900
}

.live strong {
  display:block;
  font-size:clamp(2.8rem,7vw,5.5rem);
  letter-spacing:-.06em;
  color:var(--lime)
}

.live p {
  color:var(--muted);
  margin:5px 0
}

.live a,.facts a,.deep-dive a {
  color:var(--green);
  font-size:.82rem;
  font-weight:900
}

.mother {
  border-top:1px solid var(--line)
}

.mother>p {
  max-width:850px;
  color:var(--muted);
  font-size:1.2rem;
  line-height:1.8
}

.mother blockquote {
  font-size:clamp(2.5rem,6vw,5rem);
  font-weight:950;
  letter-spacing:-.05em;
  margin:70px 0 0
}

.evidence,.cinema {
  max-width:none;
  background:var(--deep);
  padding-left:max(20px,calc((100vw - 1180px)/2));
  padding-right:max(20px,calc((100vw - 1180px)/2))
}

.heading {
  max-width:900px
}

.heading h2 {
  font-size:clamp(3rem,7vw,5.8rem)
}

.heading p {
  color:var(--muted);
  font-size:1.1rem;
  line-height:1.6
}

.facts {
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:1px;
  background:var(--line);
  margin-top:45px
}

.facts article {
  background:var(--panel);
  padding:30px;
  min-height:290px;
  display:flex;
  flex-direction:column
}

.facts small {
  color:var(--green);
  font-weight:900
}

.facts strong {
  font-size:clamp(3rem,7vw,6rem);
  letter-spacing:-.06em;
  color:var(--lime)
}

.facts p {
  color:var(--muted);
  line-height:1.6;
  margin-top:auto
}

.featured {
  display:grid;
  grid-template-columns:.8fr 1.2fr;
  border:1px solid var(--line);
  background:var(--panel);
  margin-top:40px
}

.featured>div {
  padding:32px;
  display:flex;
  flex-direction:column;
  justify-content:center
}

.featured small {
  color:var(--green);
  font-weight:900
}

.featured h3 {
  font-size:2.2rem;
  margin:10px 0
}

.featured p {
  color:var(--muted);
  line-height:1.6
}

.featured button,.featured a {
  width:max-content;
  margin-top:8px
}

.external {
  color:var(--green);
  font-weight:900
}

.featured img {
  width:100%;
  height:360px;
  object-fit:cover;
  background:#050505
}

.film-rail {
  display:flex;
  gap:10px;
  overflow-x:auto;
  padding:12px 0 18px;
  scroll-snap-type:x mandatory;
  scrollbar-width:thin;
  scrollbar-color:var(--green) var(--panel)
}

.film-rail::-webkit-scrollbar {
  height:10px
}

.film-rail::-webkit-scrollbar-track {
  background:var(--panel)
}

.film-rail::-webkit-scrollbar-thumb {
  background:var(--green);
  border-radius:10px
}

.film-rail button {
  flex:0 0 230px;
  scroll-snap-align:start;
  background:var(--panel);
  border:1px solid var(--line);
  color:white;
  padding:0;
  text-align:left;
  cursor:pointer
}

.film-rail button.active {
  border-color:var(--green)
}

.film-rail img {
  width:100%;
  aspect-ratio:16/9;
  object-fit:cover;
  background:#050505
}

.film-rail b,.film-rail small {
  display:block;
  padding:8px 10px
}

.film-rail small {
  padding-top:0;
  color:var(--muted)
}

.excuse-grid {
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:10px;
  margin-top:40px
}

.excuse-grid button {
  min-height:90px;
  background:var(--panel);
  border:1px solid var(--line);
  color:white;
  padding:20px;
  text-align:left;
  display:flex;
  align-items:center;
  gap:12px;
  font-weight:850;
  cursor:pointer
}

.excuse-grid button span {
  font-size:1.5rem
}

.excuse-grid button.active {
  border-color:var(--green);
  background:var(--panel2)
}

.deep-dive {
  margin-top:12px;
  border:1px solid var(--green);
  background:var(--deep);
  padding:32px
}

.deep-dive .back {
  background:none;
  border:0;
  color:var(--green);
  font-weight:900;
  padding:0 0 22px;
  cursor:pointer
}

.deep-dive>span,.evidence-box>span,.learn-more>span {
  color:var(--green);
  font-size:.68rem;
  letter-spacing:.12em;
  font-weight:900
}

.deep-dive h3 {
  font-size:2.1rem;
  margin:8px 0
}

.deep-dive p,.deep-dive li {
  color:var(--muted);
  line-height:1.7
}

.evidence-box {
  border-left:3px solid var(--green);
  padding-left:20px;
  margin:28px 0
}

.learn-more {
  border-top:1px solid var(--line);
  padding-top:25px;
  margin-top:25px
}

.learn-more details {
  border-bottom:1px solid var(--line);
  padding:15px 0
}

.learn-more summary {
  font-weight:850;
  cursor:pointer
}

.related-film {
  margin-top:25px;
  padding:20px;
  background:var(--panel)
}

.related-film button {
  background:none;
  border:0;
  color:var(--lime);
  font-weight:900;
  padding:0;
  cursor:pointer
}

.action-grid {
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:10px;
  margin-top:40px
}

.action-grid article {
  min-height:280px;
  background:var(--panel);
  border:1px solid var(--line);
  padding:24px;
  display:flex;
  flex-direction:column
}

.action-grid b {
  color:var(--green)
}

.action-grid h3 {
  font-size:1.5rem
}

.action-grid p {
  color:var(--muted);
  line-height:1.55
}

.action-grid button {
  margin-top:auto;
  background:none;
  border:0;
  color:var(--lime);
  font-weight:900;
  text-align:left;
  padding:0;
  cursor:pointer
}

.action-panel {
  margin-top:12px;
  padding:30px;
  background:var(--deep);
  border:1px solid var(--green)
}

.action-panel button {
  background:none;
  border:0;
  color:var(--green);
  font-weight:900;
  padding:0;
  cursor:pointer
}

.action-panel h3 {
  font-size:2rem
}

.action-panel p {
  color:var(--muted);
  line-height:1.7;
  max-width:800px
}

.final {
  text-align:center;
  padding-top:140px;
  padding-bottom:140px
}

.final p {
  max-width:800px;
  margin:auto;
  color:var(--muted);
  font-size:1.15rem;
  line-height:1.75
}

footer {
  max-width:1180px;
  margin:auto;
  border-top:1px solid var(--line);
  padding:35px 20px;
  display:flex;
  justify-content:space-between;
  color:#818b83;
  font-size:.8rem
}

.lightbox {
  position:fixed;
  inset:0;
  z-index:100;
  background:rgba(0,0,0,.94);
  padding:25px;
  place-items:center
}

.lightbox:not([hidden]) {
  display:grid
}

.modal {
  width:min(1050px,100%)
}

.modalbar {
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:12px 0
}

.modalbar small {
  display:block;
  color:var(--green)
}

.modalbar button {
  background:none;
  border:0;
  color:white;
  font-weight:900;
  cursor:pointer
}

.frame iframe {
  width:100%;
  aspect-ratio:16/9;
  border:1px solid var(--line);
  background:#000
}

.modal>p {
  color:var(--muted)
}

.modal>p a {
  color:var(--green)
}

@media(max-width:800px) {
  nav {
    display:none
  }

  .menu-btn {
    display:block
  }

  .hero {
    grid-template-columns:1fr;
    padding-top:60px
  }

  .hero-photo img {
    height:360px
  }

  .facts {
    grid-template-columns:1fr
  }

  .featured {
    grid-template-columns:1fr
  }

  .featured img {
    height:250px;
    order:-1
  }

  .excuse-grid {
    grid-template-columns:1fr 1fr
  }

  .action-grid {
    grid-template-columns:1fr 1fr
  }

}

@media(max-width:520px) {
  .hero,.mother,.evidence,.cinema,.excuses,.action,.final {
    padding-top:70px;
    padding-bottom:70px
  }

  .hero-photo img {
    height:310px
  }

  .excuse-grid,.action-grid {
    grid-template-columns:1fr
  }

  .film-rail button {
    flex-basis:78vw
  }

  .lightbox {
    padding:12px
  }

  footer {
    flex-direction:column;
    gap:7px
  }

}

.deep-dive .back {
  display:block;
  margin:0 0 28px 0;
  padding:0 0 20px;
  border-bottom:1px solid var(--line);
  width:100%;
  text-align:left
}

.deep-dive>span {
  display:block;
  margin-top:6px
}

.local-help {
  margin-top:45px;
  padding:28px;
  border:1px solid var(--line);
  background:var(--deep)
}

.local-help small {
  color:var(--green);
  font-weight:900;
  letter-spacing:.12em
}

.local-help h3 {
  font-size:1.7rem;
  margin:10px 0
}

.local-help p {
  color:var(--muted);
  line-height:1.7
}

.local-help a {
  color:var(--green);
  font-weight:900
}

@media(max-width:800px) {
  .mobile-menu {
    position:fixed;
    top:68px;
    right:0;
    left:auto;
    width:min(88vw,360px);
    height:calc(100vh - 68px);
    padding:18px;
    background:#0b0f0c;
    border-left:1px solid var(--line);
    border-bottom:0;
    box-shadow:-20px 0 50px rgba(0,0,0,.45);
    overflow-y:auto
  }

  .mobile-menu:before {
    content:"EXPLORE ZERRA";
    display:block;
    color:var(--green);
    font-size:.68rem;
    letter-spacing:.15em;
    font-weight:950;
    padding:8px 4px 18px
  }

  .mobile-menu a {
    font-size:1.05rem;
    padding:19px 8px;
    display:flex;
    align-items:center;
    gap:10px
  }

  .menu-btn[aria-expanded="true"] {
    border-color:var(--green);
    background:var(--panel2)
  }

}

.impact-photo {
  overflow:hidden;
  background:#050705
}

.impact-photo img {
  filter:none
}

.impact-photo:before {
  content:"REAL PHOTOGRAPH · NOAA FISHERIES";
  position:absolute;
  z-index:3;
  top:14px;
  left:14px;
  background:rgba(8,12,9,.82);
  border:1px solid rgba(159,226,170,.55);
  color:var(--green);
  padding:7px 9px;
  font-size:.62rem;
  letter-spacing:.12em;
  font-weight:950
}

.modal-switcher {
  display:flex;
  gap:8px;
  overflow-x:auto;
  padding:12px 0
}

.modal-switcher button {
  flex:0 0 auto;
  background:var(--panel);
  border:1px solid var(--line);
  color:var(--text);
  padding:10px 12px;
  text-align:left;
  cursor:pointer
}

.modal-switcher button.active {
  border-color:var(--green)
}

.modal-switcher span {
  display:block;
  color:var(--green);
  font-size:.65rem
}

.modal-switcher b {
  font-size:.78rem
}

.hero-copy .eyebrow {
  letter-spacing:.18em;
  font-weight:900
}

.hero-copy h1 {
  max-width:900px
}

.hero-copy h1 em {
  font-style:italic
}

.connection-bridge {
  border-top:1px solid var(--line);
  border-bottom:1px solid var(--line);
  background:#0a0d0b;
  padding:clamp(64px,9vw,118px) 0
}

.connection-inner {
  max-width:920px
}

.connection-bridge .section-kicker {
  color:var(--green);
  font-size:.72rem;
  font-weight:950;
  letter-spacing:.19em;
  margin-bottom:22px
}

.connection-bridge h2 {
  font-family:Georgia,"Times New Roman",serif;
  font-size:clamp(2.8rem,7vw,5.8rem);
  line-height:.92;
  letter-spacing:-.045em;
  margin:0;
  max-width:850px;
  color:#f4f5f1
}

.connection-bridge h2 em {
  color:var(--lime);
  font-weight:600
}

.connection-bridge p {
  max-width:710px;
  color:#bdc5be;
  font-size:clamp(1rem,1.8vw,1.18rem);
  line-height:1.72;
  margin:30px 0 0
}

.connection-chain {
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:10px;
  margin-top:38px;
  padding-top:24px;
  border-top:1px solid var(--line);
  font-size:.68rem;
  font-weight:950;
  letter-spacing:.12em;
  color:#e8ece8
}

.connection-chain b {
  color:var(--lime);
  font-size:1rem
}

@media(max-width:700px) {
  .connection-bridge {
    text-align:left
  }

  .connection-chain {
    gap:8px
  }

  .connection-chain span {
    font-size:.62rem
  }

}

.hero-photo-credit {
  margin-top:10px;
  color:#89928b;
  font-size:.68rem;
  line-height:1.45;
  letter-spacing:.035em;
}

.hero-photo-credit {
  display:block;
  margin:0 !important;
  padding:14px 16px 16px !important;
  background:#0b0e0c;
  border-top:1px solid rgba(190,255,132,.18);
  color:#b9c2bb !important;
  font-size:.78rem !important;
  line-height:1.55 !important;
  letter-spacing:.01em !important;
  font-weight:500;
}

@media(max-width:700px) {
  .hero-photo-credit {
    padding:13px 14px 15px !important;
    font-size:.76rem !important;
    line-height:1.55 !important;
  }

}

.app-page[hidden] {
  display:none!important
}

.zerra-page-nav {
  position:sticky;
  top:0;
  z-index:90;
  display:flex;
  gap:6px;
  align-items:center;
  justify-content:center;
  padding:10px 14px;
  background:rgba(8,11,9,.94);
  backdrop-filter:blur(16px);
  border-bottom:1px solid rgba(255,255,255,.08);
  overflow-x:auto
}

.zerra-page-nav button {
  appearance:none;
  border:0;
  background:transparent;
  color:#9ca69e;
  font:700 .74rem/1 system-ui,sans-serif;
  letter-spacing:.08em;
  text-transform:uppercase;
  padding:11px 13px;
  border-radius:999px;
  white-space:nowrap;
  cursor:pointer
}

.zerra-page-nav button:hover,.zerra-page-nav button.active {
  background:#c7ff8a;
  color:#0a0d0b
}

.app-page {
  min-height:70vh
}

.page-hero {
  max-width:980px;
  margin:0 auto;
  padding:clamp(76px,11vw,150px) 22px 48px
}

.page-hero>span {
  color:#c7ff8a;
  font-size:.72rem;
  font-weight:900;
  letter-spacing:.18em
}

.page-hero h1 {
  font-size:clamp(2.7rem,7vw,6.5rem);
  line-height:.92;
  letter-spacing:-.055em;
  margin:15px 0 24px;
  max-width:900px
}

.page-hero p {
  max-width:760px;
  color:#b9c2bb;
  font-size:clamp(1.05rem,2vw,1.3rem);
  line-height:1.65
}

.page-grid,.evidence-index,.resource-categories {
  max-width:1180px;
  margin:0 auto;
  padding:0 22px 100px;
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px
}

.page-grid article,.evidence-index article,.resource-categories article,.action-ladder article,.principle-callout {
  background:#111612;
  border:1px solid rgba(255,255,255,.08);
  padding:28px;
  border-radius:18px
}

.page-grid small,.evidence-index span,.resource-categories span,.principle-callout span {
  color:#c7ff8a;
  font-weight:900;
  font-size:.7rem;
  letter-spacing:.13em
}

.page-grid h2,.evidence-index h2,.resource-categories h2,.action-ladder h2,.principle-callout h2 {
  font-size:1.45rem;
  margin:10px 0
}

.page-grid p,.evidence-index p,.resource-categories p,.action-ladder p,.principle-callout p {
  color:#aeb8b0;
  line-height:1.6
}

.action-ladder {
  max-width:1180px;
  margin:0 auto;
  padding:0 22px 20px;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px
}

.action-ladder b {
  color:#c7ff8a;
  font-size:.78rem
}

.principle-callout {
  max-width:1136px;
  margin:0 auto 100px
}

@media(max-width:760px) {
  .zerra-page-nav {
    justify-content:flex-start
  }

  .page-grid,.evidence-index,.resource-categories,.action-ladder {
    grid-template-columns:1fr
  }

  .page-hero {
    padding-top:64px
  }

}

.desktop-route-nav {
  display:none!important
}

.mobile-menu {
