/* ==========================================================================
   Interior component spacing
   --------------------------------------------------------------------------
   Page backgrounds and hero sections intentionally remain full width.
   Only the grids/cards/content blocks below receive horizontal breathing room.
   ========================================================================== */

:root{
  --content-gutter:clamp(18px,3vw,40px);
  --content-max:1180px;
}

/* Why Care — inset the card grid, not the page or hero. */
.why-care-page .why-grid{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Learn — keep the black hero/full page treatment intact; inset the explanatory
   content beginning with "What is actually happening?" and its supporting bands. */
[data-page="learn"] .section-role,
[data-page="learn"] .stat-band,
[data-page="learn"] .learn-grid{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Evidence — same principle: hero stays full width, receipts/cards are inset. */
[data-page="evidence"] .section-role,
[data-page="evidence"] .evidence-grid,
[data-page="evidence"] .ledger{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Act — only the lower interactive content blocks receive the shared gutter. */
[data-page="act"] .participation-framework,
[data-page="act"] .recovery-tool{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Stores — inset the near-me/finder content without changing the page background. */
[data-page="stores"] .local-finder,
[data-page="stores"] .nearby,
[data-page="stores"] .finder-section{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Home closing CTA — give the three route cards room before the footer. */
.home-close,
.closing-cta,
.home-closing,
[data-page="home"] .closing-actions{
  padding-bottom:clamp(48px,7vw,84px) !important;
}

/* Mobile uses a predictable safe gutter around the same local components. */
@media (max-width:699px){
  :root{--content-gutter:18px;}
}


/* ==========================================================================
   Targeted responsive spacing
   ========================================================================== */

/* Home: use a compact desktop gap between the closing action cards and footer. */
@media (min-width:700px){
  .home-closing,
  [data-page="home"] .closing-actions{
    padding-bottom:clamp(24px,3.5vw,42px) !important;
  }
}

/* Evidence: inset the searchable receipt/card region itself. The hero and page
   background remain full width. */
[data-page="evidence"] .evidence-search,
[data-page="evidence"] .evidence-results,
[data-page="evidence"] .evidence-list,
[data-page="evidence"] .evidence-cards,
[data-page="evidence"] .receipt-grid,
[data-page="evidence"] .source-ledger{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Stores: `.nearby-finder` is the actual "Search what's actually around you"
   container in the current markup. */
[data-page="stores"] .nearby-finder{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

/* Evidence search, filters, and records share the same content gutter. */
[data-page="evidence"] .resource-search-wrap,
[data-page="evidence"] .evidence-ledger,
[data-page="evidence"] .evidence-record,
[data-page="evidence"] .resource-filter-row,
[data-page="evidence"] .resource-filter,
[data-page="evidence"] .active{
  width:calc(100% - (2 * var(--content-gutter))) !important;
  max-width:var(--content-max) !important;
  margin-left:auto !important;
  margin-right:auto !important;
  box-sizing:border-box !important;
}

